-- Owner-requested cleanup of the retained source-platform Spot import.
-- Exact low-quality titles were reviewed against all 4,955 live imported Spots.
-- Preserve a database-local before-state once per row, including empty text, so
-- retries are harmless and later moderator edits are not erased on restart.
-- Restore, only when explicitly requested, from this table's original_status and
-- original_description after checking for newer edits. No place/member row is deleted.
create table if not exists place_import_cleanup_20260909 (
  place_id uuid primary key,
  slug text not null,
  original_status text not null,
  original_description text not null,
  archive_reason text,
  recorded_at timestamptz not null default now()
);

