backed_up as (
  insert into place_import_cleanup_20260909
    (place_id, slug, original_status, original_description, archive_reason)
  select p.id, p.slug, p.status, p.description, rejected.reason
  from places p
  left join rejected_imports rejected on rejected.slug = p.slug and rejected.expected_name = p.name
  where p.source_kind = 'community'
    and p.slug ~ '^public-place-[a-f0-9]{24}$'
  on conflict (place_id) do nothing
  returning place_id, archive_reason
)
update places p
set description = '',
    status = case when saved.archive_reason is not null and p.status = 'published'
                  then 'archived' else p.status end,
    updated_at = now()
from backed_up saved
where p.id = saved.place_id
  and (p.description <> '' or (saved.archive_reason is not null and p.status = 'published'));
